import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForPhy2,validPhy2,advancePhy2,numericPhy2,experimentOptions,experimentResult,experimentCases,experimentValid}from './phy2-models.js?v=20261023-physicscomplete01';import{showPhy2}from './phy2-visuals.js?v=20261023-physicscomplete01';export{showPhy2};
export function mountPhy2(l,p,root,{save,done,feedback}){let ts=tasksForPhy2(l.widget.slice(5),l.learnerTier),w=p.widget;w.phy2Task??=ts[0].id;w.phy2Drafts??={};w.phy2Passed??=[];let i=ts.findIndex(t=>t.id===w.phy2Task);if(i<0)i=0;let t=ts[i],v=w.phy2Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountPhy2(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.phy2Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('phy2Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('phy2Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealPhy2">Reveal evidence →</button><p id="phy2Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showPhy2(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#phy2Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validPhy2(c,v.answer);}
else if(t.type==='sequence'){body=field('phy2Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advancePhy2">Advance pathway →</button><p id="phy2Readout" aria-live="polite"></p>';draw=()=>{showPhy2(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#phy2Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='experiment'){let o=experimentOptions[t.experiment];v.a??=o.a[0][0];v.b??=o.b[0][0];v.observed??=[];body=field('phy2A',o.labels[0],o.a,v.a)+field('phy2B',o.labels[1],o.b,v.b)+'<label class="field-label">Predict / '+o.unit+'<input class="lab-input" type="number" step="any" id="phy2Prediction" value="'+(v.prediction??'')+'"></label><button class="secondary" id="phy2Run">Reveal model output →</button><p id="phy2Output"></p>'+field('phy2Interpretation','Conclusion',[['limited','A bounded illustrative comparison; evaluate omitted effects'],['universal','This output proves the best decision for every real system']],v.interpretation);draw=()=>{let r=experimentResult(t.experiment,v.a,v.b);showPhy2(t.kind,{a:v.a,b:v.b,revealed:v.ran,title:t.title});$('#phy2Output').textContent=(v.ran?'Model output: '+Number(r.value.toFixed(3))+' '+o.unit:(t.experiment==='insulation'?'Supplied reading at10 model min: initial80°C, final'+Number(r.final.toFixed(3))+'°C. Predict the temperature drop.':'Predict first. Use the given equation or energy account.'));};valid=()=>!!v.ran&&numericPhy2(v.prediction,experimentResult(t.experiment,v.a,v.b).value);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="phy2Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="phy2Number" type="number" step="any" value="'+(v.number??'')+'">'+field('phy2Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showPhy2(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericPhy2(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="phy2Evidence"></p><div class="lab-actions"><button class="secondary" id="recordPhy2">Record reasoning</button><button class="secondary" id="nextPhy2">Next challenge →</button></div><p id="phy2Progress"></p>';
const status=()=>{$('#phy2Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='experiment'?'Recorded settings: '+v.observed.join('; '):w.phy2Passed.includes(t.id)?'Challenge recorded.':'';$('#phy2Progress').textContent=ts.filter(t=>w.phy2Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='phy2A'||id==='phy2B'){if(!val){remount();return;}v[id==='phy2A'?'a':'b']=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='phy2Interpretation'){v.interpretation=val;save();return;}if(id==='phy2Prediction'){v.prediction=val;save();return;}if(id==='phy2Case'){if(val===''){remount();return;}v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='phy2Answer')v.answer=val;else if(id==='phy2Next')v.next=val;else if(id==='phy2Number')v.number=val;else if(id==='phy2Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id==='phy2Prediction'?'prediction':'number']=e.target.value;save();};}
if($('#phy2Run'))$('#phy2Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Predict a number first.',true);return;}v.ran=true;save();draw();};
if($('#revealPhy2'))$('#revealPhy2').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validPhy2(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validPhy2(t.cases[v.case],v.answer));};
if($('#advancePhy2'))$('#advancePhy2').onclick=()=>{let n=advancePhy2(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordPhy2').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='experiment'){let key=v.a+':'+v.b;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='experiment'?experimentValid(t.experiment,v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.phy2Passed.includes(t.id))w.phy2Passed.push(t.id);p.widgetDone=ts.every(t=>w.phy2Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':t.type==='experiment'&&experimentCases(t.experiment).every(k=>v.observed.includes(k))?'All required settings recorded. Choose a conclusion that respects the model limits.':'Recorded. Compare the remaining scenarios.');};$('#nextPhy2').onclick=()=>{if(!w.phy2Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.phy2Task=ts[(i+1)%ts.length].id;save();remount();};}
